export class DuckDbOp extends Operator<DuckDbOp> {
  static displayName = 'DuckDB'
  static description = 'Query a DuckDB database using sql'
  asDownload = () => this.outputData
  createInputs() {
    return {
      query: new CodeField('SELECT 1 as val;', { language: 'sql' }),
    }
  }
  createOutputs() {
    return {
      data: new DataField(),
    }
  }

  async execute({
    query: queryString = '',
  }: ExtractProps<typeof this.inputs>): ExtractProps<typeof this.outputs> | null {
    const queries = queryString
      .split(';')
      .map(s => s.trim())
      .filter(Boolean)
      .map(s => `${s};`)
    if (!queries?.length) {
      return { data: [] }
    }

    const db = await duckDbInstance
    const conn = await db.connect()

    try {
      let data = []
      for (const query of queries) {
        if (!mustacheRe.test(query)) {
          const result = await conn.query(query)
          data = result.toArray()
          continue
        }

        // Parse the query and extract references
        const references: FieldReference[] = []
        const parameterizedQuery = query.replace(mustacheRe, (raw, opId, inOut, fieldPath) => {
          // If the opId is a relative path (doesn't start with /), make it relative to current context
          const resolvedOpId = opId.startsWith('/') ? opId : `./${opId}`
          references.push({ opId: resolvedOpId, inOut, fieldPath, raw })
          return `$${references.length}` // $1, $2, etc.
        })

        // Resolve reference values
        const positionalParams = references.map(({ opId, inOut, fieldPath }) => {
          const op = getOp(opId, this.id)
          const [firstKey, ...rest] = fieldPath.split('.')

          const field = op?.[inOut === 'par' ? 'inputs' : 'outputs']?.[firstKey]
          if (!field) {
            throw new Error(`Field ${firstKey} not found on ${opId}`)
          }

          return rest.reduce((d, prop) => d[prop], field.value)
        })

        // Prepare the query with the current connection
        const prepared = await conn.prepare(parameterizedQuery)

        const result = await prepared.query(...positionalParams)
        data = result.toArray()
      }
      await conn.close()
      return { data }
    } catch (e) {
      debugExecute('Error executing query', e)
      await conn.close()
      await db.reset()
      if (e instanceof Error) {
        throw e
      }
      return null
    }
  }
}

const duckDbInstance = (async () => {
  // Use CDN bundles for Cloudflare Pages (which has a 25 MiB file size limit)
  // Use local bundles for development and GitHub Actions (which can access local files)
  let bundles: duckdb.DuckDBBundles

  // Use import.meta.env directly in the condition for proper tree-shaking
  if (import.meta.env.VITE_USE_CDN_DUCKDB === 'true') {
    // jsdelivr CDN hosts the large WASM files externally
    bundles = duckdb.getJsDelivrBundles()
  } else {
    // Dynamically import the WASM files only when not using CDN
    // Vite will tree-shake this entire branch when VITE_USE_CDN_DUCKDB is 'true'
    const [
      duckdb_wasm,
      mvp_worker,
      duckdb_wasm_eh,
      eh_worker,
      duckdb_wasm_coi,
      coi_worker,
      duckdb_pthread_worker,
    ] = await Promise.all([
      import('@duckdb/duckdb-wasm/dist/duckdb-mvp.wasm?url').then(m => m.default),
      import('@duckdb/duckdb-wasm/dist/duckdb-browser-mvp.worker.js?url').then(m => m.default),
      import('@duckdb/duckdb-wasm/dist/duckdb-eh.wasm?url').then(m => m.default),
      import('@duckdb/duckdb-wasm/dist/duckdb-browser-eh.worker.js?url').then(m => m.default),
      import('@duckdb/duckdb-wasm/dist/duckdb-coi.wasm?url').then(m => m.default),
      import('@duckdb/duckdb-wasm/dist/duckdb-browser-coi.worker.js?url').then(m => m.default),
      import('@duckdb/duckdb-wasm/dist/duckdb-browser-coi.pthread.worker.js?url').then(
        m => m.default
      ),
    ])

    // Bundle the WASM files locally for environments that support it
    bundles = {
      mvp: {
        mainModule: duckdb_wasm,
        mainWorker: mvp_worker,
      },
      eh: {
        mainModule: duckdb_wasm_eh,
        mainWorker: eh_worker,
      },
      coi: {
        mainModule: duckdb_wasm_coi,
        mainWorker: coi_worker,
        pthreadWorker: duckdb_pthread_worker,
      },
    }
  }

  // Select a bundle based on browser checks
  const bundle = await duckdb.selectBundle(bundles)
  const workerUrl = bundle.mainWorker!

  // Handle cross-origin URLs by fetching and creating blob URL
  const isCrossOrigin =
    workerUrl.startsWith('http') && !workerUrl.startsWith(window.location.origin)
  const resolvedWorkerUrl = isCrossOrigin
    ? await fetch(workerUrl).then(async res => {
        if (!res.ok) {
          throw new Error(`Failed to fetch DuckDB worker: ${res.status} ${res.statusText}`)
        }
        const blob = new Blob([await res.text()], { type: 'application/javascript' })
        return URL.createObjectURL(blob)
      })
    : workerUrl

  const worker = new Worker(resolvedWorkerUrl)
  const logger = new duckdb.ConsoleLogger(duckdb.LogLevel.WARNING)
  const db = new duckdb.AsyncDuckDB(logger, worker)
  await db.instantiate(bundle.mainModule, bundle.pthreadWorker)

  const conn = await db.connect()
  await conn.query(`
    SET autoinstall_known_extensions = 1;
    INSTALL spatial;
    LOAD spatial;
    INSTALL httpfs;
    -- Not sure why but this isn't loading. For some reason it still works in the code though
    -- LOAD httpfs;
  `)
  await conn.close()

  return db
})()

import { execSync } from 'node:child_process'
import fs from 'node:fs'
import path from 'node:path'
import react from '@vitejs/plugin-react'
import { defineConfig, loadEnv } from 'vite'
import { nodePolyfills } from 'vite-plugin-node-polyfills'

const ENV_VARIABLES_WITH_INSTRUCTIONS = {
  VITE_GOOGLE_MAPS_API_KEY:
    'Get token at https://developers.google.com/maps/documentation/javascript/get-api-key',
  VITE_CESIUM_ACCESS_TOKEN: 'Get token at https://cesium.com/ion/tokens',
  VITE_MAPBOX_ACCESS_TOKEN: 'Get token at https://account.mapbox.com/access-tokens/',
  VITE_MAPTILER_API_KEY: 'Get token at https://cloud.maptiler.com/account/keys/',
  VITE_CLAUDE_API_KEY: 'Get token at https://console.anthropic.com/ (Optional - can be set in UI)',
}

// Vite plugin to auto-regenerate AI context bundles when relevant files change
function contextGeneratorPlugin() {
  let isGenerating = false
  let needsRegeneration = false

  const watchedPaths = [
    'src/noodles/operators.ts',
    'src/noodles/fields.ts',
    'src/noodles/components/categories.ts',
    'src/ai-chat/**/*.md',
    'src/examples/**/noodles.json',
    'src/examples/**/README.md',
  ]

  async function generateContext() {
    if (isGenerating) {
      needsRegeneration = true
      return
    }

    isGenerating = true
    needsRegeneration = false

    try {
      console.log('\n🔄 Regenerating AI context bundles...')
      execSync('npm run generate:context', {
        stdio: 'inherit',
        cwd: process.cwd(),
      })
      console.log('✅ AI context bundles updated\n')
    } catch (error) {
      console.error('❌ Failed to generate context:', error.message)
    } finally {
      isGenerating = false

      // If files changed while we were generating, trigger another generation
      if (needsRegeneration) {
        setTimeout(() => generateContext(), 100)
      }
    }
  }

  return {
    name: 'context-generator',
    apply: 'serve', // Only run in dev mode
    configureServer(server) {
      // Generate context on server start
      generateContext()

      // Watch for file changes
      server.watcher.on('change', file => {
        const relativePath = path.relative(server.config.root, file)

        // Check if the changed file matches any watched patterns
        const shouldRegenerate = watchedPaths.some(pattern => {
          if (pattern.includes('**')) {
            const regex = new RegExp(`^${pattern.replace(/\*\*/g, '.*').replace(/\*/g, '[^/]*')}$`)
            return regex.test(relativePath)
          }
          return relativePath === pattern
        })

        if (shouldRegenerate) {
          console.log(`📝 Detected change in ${relativePath}`)
          generateContext()
        }
      })
    },
  }
}

export default defineConfig(({ mode }) => {
  // Load env file based on `mode` in the current working directory.
  // Set the third parameter to '' to load all env regardless of the `VITE_` prefix.
  const env = loadEnv(mode, process.cwd(), '')

  // Log helpful messages for missing optional environment variables in development
  if (mode === 'development') {
    Object.entries(ENV_VARIABLES_WITH_INSTRUCTIONS).forEach(([key, instruction]) => {
      if (!env[key]) {
        console.log(`ℹ️  ${key} not set. ${instruction}`)
      }
    })
  }

  return {
    base: mode === 'development' ? '/' : '/app/',
    server: {
      open: true,
    },
    // duckdb-wasm bundles WASM + worker files that break Vite's dep optimization
    optimizeDeps: {
      exclude: ['@duckdb/duckdb-wasm'],
    },
    plugins: [
      react(),
      nodePolyfills({
        protocolImports: true,
      }),
      contextGeneratorPlugin(),
      {
        name: 'dev-asset-404',
        enforce: 'pre', // run before vite's history fallback
        configureServer(server) {
          const publicDir = server.config.publicDir
          const root = server.config.root

          server.middlewares.use((req, res, next) => {
            let url = req.url || '/'
            url = decodeURIComponent(url.split('?')[0])

            // let Vite handle its own virtual/internal paths and hoisted node_modules
            if (url.startsWith('/@') || url.startsWith('/node_modules/')) {
              next()
              return
            }

            // if it looks like a file request (has an extension)...
            if (/\.[a-zA-Z0-9]{1,8}$/.test(url)) {
              const safe = path.posix.normalize(url).replace(/^(\.\.[/\\])+/, '')

              const candidates = [
                publicDir && path.join(publicDir, safe),
                path.join(root, safe),
              ].filter(Boolean)

              const exists = candidates.some(p => fs.existsSync(p))
              if (!exists) {
                res.statusCode = 404
                res.end('Not found')
                return
              }
            }

            next()
          })
        },
      },
    ],
  }
})

